"""Offline visuals: one distinct gradient PNG per scene, generated by ffmpeg."""

from __future__ import annotations

from pathlib import Path

from ..models import HEIGHT, WIDTH, Script, VisualAsset
from ..render import ffmpeg

_PALETTE = ["0x1b3a4b", "0x3d1f4d", "0x0f4c5c", "0x4a1942", "0x1e3d59", "0x2b2d42"]


class MockVisuals:
    def generate(self, script: Script, out_dir: Path) -> list[VisualAsset]:
        assets: list[VisualAsset] = []
        count = len(script.scenes) + 1  # hook + scenes
        for index in range(count):
            colour = _PALETTE[index % len(_PALETTE)]
            target = out_dir / f"scene_{index:02d}.png"
            ffmpeg.run(
                [
                    "-f",
                    "lavfi",
                    "-i",
                    f"gradients=size={WIDTH}x{HEIGHT}:c0={colour}:c1=0x000000:nb_colors=2",
                    "-frames:v",
                    "1",
                    str(target),
                ]
            )
            assets.append(VisualAsset(scene_index=index, path=target, kind="image"))
        return assets
